SELECT COUNT(1) FROM ai_capability_client c WHERE c.del_flag = 0 AND c.status = 'ENABLED' AND (c.expires_at IS NULL OR c.expires_at > NOW()) AND ( c.tenant_id IS NULL OR c.tenant_id <= 0 OR LOWER(c.client_code) IN
#{code}
OR CHAR_LENGTH(c.key_id) <> 22 OR CHAR_LENGTH(c.key_hash) <> 64 OR c.credential_version IS NULL OR c.credential_version <= 0 OR c.actor_mode IS NULL OR c.actor_mode NOT IN ('USER_DELEGATION', 'SERVICE', 'HYBRID') OR c.auth_modes IS NULL OR REPLACE(UPPER(c.auth_modes), ' ', '') NOT IN ('OAUTH', 'SIGNATURE', 'OAUTH,SIGNATURE', 'SIGNATURE,OAUTH') OR (c.oauth_enabled = 1 AND FIND_IN_SET('OAUTH', REPLACE(UPPER(c.auth_modes), ' ', '')) = 0) OR (FIND_IN_SET('OAUTH', REPLACE(UPPER(c.auth_modes), ' ', '')) > 0 AND (c.oauth_enabled IS NULL OR c.oauth_enabled <> 1 OR c.oauth_client_type NOT IN ('PUBLIC', 'CONFIDENTIAL'))) OR (FIND_IN_SET('SIGNATURE', REPLACE(UPPER(c.auth_modes), ' ', '')) > 0 AND (c.signing_key_cipher IS NULL OR c.signing_key_cipher = '' OR c.signing_key_version IS NULL OR c.signing_key_version <= 0)) OR (c.actor_mode = 'USER_DELEGATION' AND (c.service_user_id IS NOT NULL OR c.active_org_id IS NOT NULL)) OR (c.actor_mode IN ('SERVICE', 'HYBRID') AND ( c.service_user_id IS NULL OR c.service_user_id <= 0 OR c.active_org_id IS NULL OR c.active_org_id <= 0 OR NOT EXISTS ( SELECT 1 FROM sys_user u WHERE u.id = c.service_user_id AND u.tenant_id = c.tenant_id AND u.user_status = 1 AND u.user_type <> 0 AND u.force_password_change = 0 AND u.del_flag = 0 ) OR NOT EXISTS ( SELECT 1 FROM sys_org o WHERE o.id = c.active_org_id AND o.tenant_id = c.tenant_id AND o.org_status = 1 AND o.del_flag = 0 ) OR NOT EXISTS ( SELECT 1 FROM sys_user_org uo WHERE uo.tenant_id = c.tenant_id AND uo.user_id = c.service_user_id AND uo.org_id = c.active_org_id ) OR NOT EXISTS ( SELECT 1 FROM sys_user_org_role uor WHERE uor.tenant_id = c.tenant_id AND uor.user_id = c.service_user_id AND uor.org_id = c.active_org_id ) )) )

SELECT COUNT(1) FROM ai_capability_grant g LEFT JOIN ai_capability_client c ON c.id = g.client_id AND c.tenant_id = g.tenant_id AND c.del_flag = 0 LEFT JOIN ai_capability a ON a.id = g.capability_id AND a.tenant_id = g.tenant_id AND a.del_flag = 0 LEFT JOIN ai_capability_version v ON v.capability_id = g.capability_id AND v.tenant_id = g.tenant_id AND v.version = CASE WHEN g.version_strategy = 'FOLLOW_MAJOR' AND SUBSTRING_INDEX(a.current_version, '.', 1) = SUBSTRING_INDEX(g.fixed_version, '.', 1) THEN a.current_version ELSE g.fixed_version END AND v.del_flag = 0 WHERE g.del_flag = 0 AND g.status = 'ENABLED' AND (g.expires_at IS NULL OR g.expires_at > NOW()) AND ( g.tenant_id IS NULL OR g.tenant_id <= 0 OR c.id IS NULL OR c.status <> 'ENABLED' OR (c.expires_at IS NOT NULL AND c.expires_at <= NOW()) OR LOWER(c.client_code) IN
#{code}
OR a.id IS NULL OR a.publish_status <> 'PUBLISHED' OR a.enabled <> 1 OR g.version_strategy NOT IN ('PINNED', 'FOLLOW_MAJOR') OR g.fixed_version IS NULL OR g.fixed_version = '' OR v.id IS NULL OR v.status <> 'PUBLISHED' OR (a.source_type = 'BUSINESS_ACTION' AND a.behavior = 'ACTION' AND (g.field_policy IS NULL OR JSON_LENGTH(g.field_policy) = 0)) OR (a.source_type = 'FLOW_ACTION' AND a.behavior = 'FLOW' AND (g.field_policy IS NULL OR JSON_LENGTH(g.field_policy) = 0)) )
